def seed_database():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("DROP TABLE IF EXISTS reference_snps")
    c.execute("""
        CREATE TABLE reference_snps (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            rsid TEXT,
            category TEXT,
            trait TEXT,
            description TEXT,
            risk_allele TEXT,
            risk_genotype TEXT,
            risk_level TEXT,
            population_freq REAL,
            study_url TEXT,
            note TEXT
        )
    """)
    c.execute("CREATE INDEX idx_rsid ON reference_snps(rsid)")
    c.execute("CREATE INDEX idx_category ON reference_snps(category)")

    for snp in CURATED_SNPS:
        c.execute("""
            INSERT INTO reference_snps (rsid, category, trait, description, risk_allele, risk_genotype, risk_level, population_freq, study_url, note)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (snp[0], snp[1], snp[2], snp[3], snp[4], snp[5], snp[6], snp[7], snp[8], snp[9]))

    conn.commit()
    conn.close()
    print(f"Seeded {len(CURATED_SNPS)} SNP-trait associations into {DB_PATH}")

if __name__ == "__main__":
    seed_database()
